            {"stem": "Why was the hallway display installed?", "skill_focus": "purpose", "evidence": "turns an invisible energy system into a daily science lesson", "explanation": "The display helps students see and learn from the energy data.", "choices": [c("To help students learn from the energy data", True, "The principal explains its educational purpose."), c("To advertise the solar company", False, "No company is advertised."), c("To reduce hallway lighting costs", False, "The display does not save lighting energy."), c("To replace the classroom boards", False, "No classroom boards are replaced.")]},
            {"stem": "What will the annual savings be used for?", "skill_focus": "detail", "evidence": "divided between classroom supplies and a new shade structure", "explanation": "Savings will support supplies and playground shade.", "choices": [c("Classroom supplies and a shade structure", True, "Both are named."), c("Teacher salaries only", False, "Salaries are not mentioned."), c("A new gym roof", False, "The roof is already fitted."), c("More solar panels at the same school", False, "Monitoring may lead to panels at other schools.")]},
