            {"stem": "What do privacy groups want?", "skill_focus": "detail", "evidence": "clear rules about who can view the footage and how long it is stored", "explanation": "Privacy groups want limits on access and storage.", "choices": [c("Clear rules on access and storage", True, "This is their request."), c("No cameras anywhere", False, "They oppose the plan but focus on safeguards."), c("More cameras in parks", False, "They do not ask for more cameras."), c("Public release of all footage", False, "They want restricted access.")]},
            {"stem": "What concern do social service groups raise?", "skill_focus": "inference", "evidence": "cameras may push vulnerable people away ... without addressing root causes", "explanation": "They worry cameras may displace vulnerable people instead of solving underlying issues.", "choices": [c("Cameras may displace vulnerable people without solving root causes", True, "This captures their concern."), c("Cameras are too expensive", False, "Cost is not their focus."), c("Cameras will reduce lighting", False, "They mention inadequate lighting as a root cause."), c("Cameras will help outreach workers", False, "They do not claim this.")]},
